569	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
570	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
571	func authzCurrentStatus(a authzRec, now time.Time) string {
572		switch a.Status {
573		case "revoked":
574			return AuthRevoked
575		case "used":
576			return AuthUsed
577		}
578		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
579			return AuthExpired
580		}
581		return AuthActive
582	}
